templates.css:
:root{
  --fondo:#0F1411;
  --panel:#161D19;
  --panel-hondo:#121813;
  --crema:#EEE6D6;
  --tenue:#B1AA9B;
  --bronce:#C29A62;
  --bronce-claro:#D9B988;
  --tinta:#15110B;
  --linea:rgba(238,230,214,.14);
  --serif:'Bodoni Moda',Didot,'Times New Roman',serif;
  --sans:'Hanken Grotesk',system-ui,-apple-system,'Segoe UI',sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;overflow-x:clip;scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
body{
  margin:0;
  background:var(--fondo);
  color:var(--crema);
  font-family:var(--sans);
  font-size:1.0625rem;
  line-height:1.65;
  font-weight:400;
  overflow-x:clip;
  padding-bottom:5.75rem;
  -webkit-font-smoothing:antialiased;
}
img{display:block;max-width:100%}
a{color:inherit}
::selection{background:var(--bronce);color:var(--tinta)}
:focus-visible{outline:2px solid var(--bronce-claro);outline-offset:3px;border-radius:2px}
[id]{scroll-margin-top:1.5rem}

.envoltura{width:min(1180px,calc(100% - 2.5rem));margin-inline:auto}

/* Franja de propuesta */
.aviso{
  margin:0;
  background:var(--panel);
  border-bottom:1px solid var(--bronce);
  color:var(--crema);
  text-align:center;
  font-size:1rem;
  line-height:1.45;
  padding:.75rem 1.25rem;
}

/* Botones */
.boton{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:48px;
  padding:.7rem 1.6rem;
  background:var(--bronce);
  color:var(--tinta);
  border:1px solid var(--bronce);
  border-radius:2px;
  font-family:var(--sans);
  font-size:1rem;
  font-weight:600;
  letter-spacing:.02em;
  line-height:1.2;
  text-align:center;
  text-decoration:none;
  transition:background-color .2s ease,border-color .2s ease,color .2s ease;
}
.boton:hover{background:var(--bronce-claro);border-color:var(--bronce-claro)}
.boton-linea{background:transparent;color:var(--crema);border-color:rgba(238,230,214,.38)}
.boton-linea:hover{background:transparent;color:var(--bronce-claro);border-color:var(--bronce)}

/* Cabecera */
.cabecera{padding:1.1rem 0 .5rem}
.cabecera .envoltura{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  justify-content:space-between;
  gap:.25rem 2rem;
}
.marca{
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-size:1.65rem;
  font-weight:500;
  line-height:1.15;
  text-decoration:none;
  color:var(--crema);
  min-height:44px;
  display:inline-flex;
  align-items:center;
  overflow-wrap:anywhere;
}
.menu{display:flex;flex-wrap:wrap;gap:0 1.25rem;width:100%}
.menu a{
  min-height:44px;
  display:inline-flex;
  align-items:center;
  color:var(--tenue);
  font-size:1rem;
  text-decoration:none;
  text-underline-offset:.35em;
  text-decoration-thickness:1px;
}
.menu a:hover{color:var(--crema);text-decoration:underline;text-decoration-color:var(--bronce)}
.cabecera-cta{display:none}

/* Portada */
.portada{
  padding:2.5rem 0 5rem;
  background:
    radial-gradient(ellipse 70% 60% at 85% 10%,rgba(194,154,98,.09),transparent 70%),
    radial-gradient(ellipse 60% 50% at 0% 100%,rgba(22,29,25,.9),transparent 70%);
}
.portada .envoltura{display:grid;grid-template-columns:minmax(0,1fr);gap:3.75rem}
.titular{
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:400;
  font-size:clamp(2.75rem,6.4vw,5.75rem);
  line-height:1.03;
  letter-spacing:-.012em;
  margin:0 0 1.5rem;
  color:var(--crema);
  overflow-wrap:break-word;
  text-wrap:balance;
}
.bajada{
  margin:0 0 2.25rem;
  max-width:34em;
  color:var(--tenue);
  font-size:1.125rem;
  line-height:1.65;
}
.acciones{display:flex;flex-wrap:wrap;gap:.75rem}
.portada-dir{
  margin:2rem 0 0;
  padding-top:1.25rem;
  border-top:1px solid var(--linea);
  color:var(--tenue);
  font-size:1rem;
  max-width:30em;
}
.portada-dir a{text-decoration:none}
.portada-dir a:hover{color:var(--crema);text-decoration:underline;text-decoration-color:var(--bronce);text-underline-offset:.3em}

/* El espejo: arco con marco de bronce y repisa */
.espejo{
  position:relative;
  width:min(calc(100% - 2.5rem),440px);
  aspect-ratio:3/4;
  margin:0 auto 1.75rem;
}
.espejo::before{
  content:"";
  position:absolute;
  inset:-14px;
  border:1px solid var(--bronce);
  border-radius:1000px 1000px 3px 3px;
  pointer-events:none;
}
.espejo::after{
  content:"";
  position:absolute;
  left:-1.25rem;
  right:-1.25rem;
  bottom:-28px;
  height:1px;
  background:var(--bronce);
}
.espejo-marco{
  position:absolute;
  inset:0;
  overflow:hidden;
  border-radius:1000px 1000px 2px 2px;
  background:var(--panel);
}
.espejo-marco img{
  width:100%;
  height:100%;
  object-fit:cover;
  animation:revelar 1.4s cubic-bezier(.2,.7,.2,1) both;
}
.espejo-marco.sin-foto{
  display:grid;
  place-items:center;
  padding:3rem 1.75rem 2rem;
  background:
    radial-gradient(circle at 50% 28%,rgba(194,154,98,.18),transparent 62%),
    linear-gradient(180deg,var(--panel) 0%,var(--panel-hondo) 100%);
}
.espejo-marco.sin-foto::before{
  content:"";
  position:absolute;
  inset:16px;
  border:1px solid rgba(194,154,98,.32);
  border-radius:1000px 1000px 2px 2px;
}
.espejo-nombre{
  position:relative;
  margin:0;
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:400;
  font-size:clamp(2rem,6vw,3.25rem);
  line-height:1.08;
  text-align:center;
  color:var(--bronce-claro);
  overflow-wrap:anywhere;
  text-wrap:balance;
  animation:revelar 1.4s cubic-bezier(.2,.7,.2,1) both;
}
@keyframes revelar{
  from{opacity:0;transform:scale(1.05)}
  to{opacity:1;transform:none}
}
@media (prefers-reduced-motion:reduce){
  .espejo-marco img,.espejo-nombre{animation:none}
}

/* Secciones */
.seccion{padding:5rem 0;border-top:1px solid var(--linea)}
.seccion-grilla{display:grid;grid-template-columns:minmax(0,1fr);gap:2.5rem}
.seccion-titulo{
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:400;
  font-size:clamp(2.25rem,4.4vw,3.5rem);
  line-height:1.08;
  margin:0;
  color:var(--crema);
}
.seccion-titulo::after{
  content:"";
  display:block;
  width:3rem;
  height:1px;
  margin-top:1.25rem;
  background:var(--bronce);
}

/* Carta de servicios */
.carta{list-style:none;margin:0;padding:0;border-top:1px solid var(--linea)}
.plato{
  display:grid;
  grid-template-columns:minmax(0,1fr);
  grid-template-areas:"t" "d" "b";
  gap:.6rem;
  padding:1.9rem 0;
  border-bottom:1px solid var(--linea);
}
.plato-titulo{
  grid-area:t;
  margin:0;
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:500;
  font-size:1.6rem;
  line-height:1.2;
  overflow-wrap:break-word;
}
.puntos{grid-area:p;display:none}
.plato-desc{grid-area:d;margin:0;color:var(--tenue);max-width:44ch}
.plato .boton{grid-area:b;justify-self:start;margin-top:.6rem}

/* Galería */
.galeria{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:.6rem;
  margin:0;
  padding:0;
  list-style:none;
}
.galeria li{
  aspect-ratio:4/5;
  overflow:hidden;
  background:var(--panel);
  border-radius:2px;
}
.galeria img{width:100%;height:100%;object-fit:cover}

/* Nosotros */
.sobre{
  margin:0 0 2.75rem;
  max-width:34em;
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:500;
  font-size:1.3rem;
  line-height:1.6;
  color:var(--crema);
}
.sellos{
  list-style:none;
  margin:0;
  padding:0;
  display:grid;
  grid-template-columns:minmax(0,1fr);
  gap:1.5rem 2.5rem;
}
.sellos li{
  position:relative;
  padding-top:1rem;
  border-top:1px solid var(--linea);
  color:var(--tenue);
  font-size:1.0625rem;
}
.sellos li::before{
  content:"";
  position:absolute;
  top:-1px;
  left:0;
  width:2rem;
  height:1px;
  background:var(--bronce);
}

/* Contacto */
.contacto-cta{margin:0 0 3rem}
.contacto-grilla{display:grid;grid-template-columns:minmax(0,1fr);gap:2.75rem}
.dato-titulo{
  margin:0;
  font-family:var(--sans);
  font-size:1rem;
  font-weight:500;
  color:var(--tenue);
}
.dato-valor{
  margin:.35rem 0 1.25rem;
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:500;
  font-size:1.6rem;
  line-height:1.25;
  overflow-wrap:anywhere;
}
.dato-valor a{text-decoration:none}
.dato-valor a:hover{text-decoration:underline;text-decoration-color:var(--bronce);text-underline-offset:.2em;text-decoration-thickness:1px}

/* Pie */
.pie{border-top:1px solid var(--linea);padding:3rem 0 2.5rem;background:var(--panel-hondo)}
.pie .envoltura{display:grid;grid-template-columns:minmax(0,1fr);gap:1.75rem}
.pie-nombre{
  margin:0;
  font-family:var(--serif);
  font-optical-sizing:auto;
  font-weight:500;
  font-size:1.5rem;
  line-height:1.2;
  color:var(--bronce-claro);
  overflow-wrap:anywhere;
}
.pie-datos{margin:0;padding:0;list-style:none;color:var(--tenue);font-size:1rem}
.pie-datos a{
  display:inline-flex;
  align-items:center;
  min-height:44px;
  text-decoration:none;
}
.pie-datos a:hover{color:var(--crema);text-decoration:underline;text-decoration-color:var(--bronce);text-underline-offset:.3em}
.pie .menu{width:auto}

/* Barra fija en celular */
.barra{
  position:fixed;
  left:0;
  right:0;
  bottom:0;
  z-index:30;
  display:flex;
  gap:.5rem;
  padding:.65rem 1rem calc(.65rem + env(safe-area-inset-bottom));
  background:rgba(15,20,17,.95);
  border-top:1px solid var(--linea);
  -webkit-backdrop-filter:blur(8px);
  backdrop-filter:blur(8px);
}
.barra .boton{flex:1 1 auto;min-height:50px}
.barra .boton-linea{flex:0 0 auto;padding-inline:1.25rem}

@media (min-width:640px){
  .galeria{grid-template-columns:repeat(3,minmax(0,1fr));gap:.9rem}
  .sellos{grid-template-columns:repeat(2,minmax(0,1fr))}
  .contacto-grilla{grid-template-columns:repeat(2,minmax(0,1fr))}
}

@media (min-width:760px){
  .plato{
    grid-template-columns:minmax(0,max-content) minmax(2rem,1fr) auto;
    grid-template-areas:"t p b" "d d .";
    column-gap:1.25rem;
    row-gap:.5rem;
  }
  .puntos{
    display:block;
    align-self:center;
    height:0;
    border-bottom:1px dotted rgba(194,154,98,.6);
    transform:translateY(.35rem);
  }
  .plato .boton{align-self:center;margin-top:0}
  .plato-titulo{font-size:1.85rem}
}

@media (min-width:900px){
  body{padding-bottom:0}
  .barra{display:none}
  .cabecera{padding:1.5rem 0}
  .cabecera .envoltura{flex-wrap:nowrap}
  .menu{width:auto;margin-left:auto;gap:0 2rem}
  .cabecera-cta{display:inline-flex}
  .portada{padding:4.5rem 0 7rem}
  .portada .envoltura{
    grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);
    gap:5rem;
    align-items:center;
  }
  .espejo{margin-bottom:0}
  .espejo::after{left:-2.5rem;right:-2.5rem}
  .seccion{padding:7rem 0}
  .seccion-grilla{grid-template-columns:minmax(0,1fr) minmax(0,2.1fr);gap:4rem}
  .seccion-cabeza{position:sticky;top:2rem;align-self:start}
  .sobre{font-size:1.5rem}
  .pie .envoltura{grid-template-columns:minmax(0,1fr) auto auto;align-items:start;gap:3rem}
}

:root{
  --papel:#FFFFFF;
  --hormigon:#ECEDEA;
  --linea:#C8CBC7;
  --tinta:#1C2225;
  --gris:#4F585D;
  --grafito:#283034;
  --gris-claro:#B9C0C3;
  --senal:#EFC23A;
  --ancho:76rem;
  --margen:clamp(1.25rem,5vw,4rem);
  --sans:"Archivo",system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono:"Spline Sans Mono",ui-monospace,"Cascadia Mono",monospace;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{
  margin:0;
  font-family:var(--sans);
  font-size:1.0625rem;
  line-height:1.6;
  color:var(--tinta);
  background:var(--papel);
  overflow-x:clip;
  padding-bottom:calc(4.5rem + env(safe-area-inset-bottom));
}
img{display:block;max-width:100%;height:auto}
a{color:inherit}
h1,h2,h3{text-wrap:balance;overflow-wrap:break-word}
p{overflow-wrap:break-word}
:focus-visible{outline:3px solid var(--tinta);outline-offset:3px}
.oscuro :focus-visible{outline-color:var(--senal)}

.saltar{position:absolute;left:-9999px;top:0}
.saltar:focus{left:1rem;top:1rem;z-index:40;background:var(--papel);color:var(--tinta);padding:.75rem 1rem;min-height:44px}

/* Franja de propuesta */
.aviso{background:var(--tinta);color:#F3F4F2;padding:.75rem var(--margen);font-size:1rem;line-height:1.45}
.aviso p{max-width:var(--ancho);margin:0 auto;display:flex;gap:.75rem;align-items:baseline}
.aviso p::before{content:"";flex:0 0 auto;width:.6rem;height:.6rem;background:var(--senal);transform:translateY(-.05rem)}

/* Encabezado */
.cab{background:var(--papel);border-bottom:1px solid var(--linea)}
.cab__in{max-width:var(--ancho);margin:0 auto;padding:.5rem var(--margen);display:flex;flex-wrap:wrap;align-items:center;gap:0 2rem;min-height:4.5rem}
.cab__nombre{margin-right:auto;display:inline-flex;align-items:center;min-height:44px;font-size:1.125rem;font-weight:600;font-stretch:112%;letter-spacing:-.01em;line-height:1.2;text-decoration:none}
.cab nav{width:100%}
.menu{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:0 1.25rem}
.menu a{display:inline-flex;align-items:center;min-height:44px;font-size:1rem;color:var(--gris);text-decoration:none;text-underline-offset:.4em;text-decoration-thickness:1px}
.menu a:hover{color:var(--tinta);text-decoration-line:underline}
.menu a[aria-current="page"]{color:var(--tinta);text-decoration-line:underline}
.cab .boton{display:none}

/* Botones */
.boton{
  display:inline-flex;align-items:center;justify-content:center;
  min-height:3rem;padding:.75rem 1.5rem;
  font:inherit;font-size:1rem;font-weight:500;line-height:1.2;text-align:center;
  text-decoration:none;
  background:var(--tinta);color:#fff;border:1px solid var(--tinta);border-radius:0;
  transition:background-color .15s ease,border-color .15s ease,color .15s ease;
}
.boton:hover{background:var(--grafito);border-color:var(--grafito)}
.boton--linea{background:transparent;color:var(--tinta)}
.boton--linea:hover{background:var(--tinta);color:#fff}
.oscuro .boton{background:var(--senal);color:var(--tinta);border-color:var(--senal)}
.oscuro .boton:hover{background:#fff;border-color:#fff}
.oscuro .boton--linea{background:transparent;color:#fff;border-color:rgba(255,255,255,.7)}
.oscuro .boton--linea:hover{background:#fff;color:var(--tinta);border-color:#fff}
.boton--chico{min-height:44px;padding:.5rem 1.1rem}

/* Marcas de encuadre */
.esquinas{
  --m:var(--senal);--l:1.75rem;--g:2px;
  background:
    linear-gradient(var(--m),var(--m)) top left/var(--l) var(--g) no-repeat,
    linear-gradient(var(--m),var(--m)) top left/var(--g) var(--l) no-repeat,
    linear-gradient(var(--m),var(--m)) top right/var(--l) var(--g) no-repeat,
    linear-gradient(var(--m),var(--m)) top right/var(--g) var(--l) no-repeat,
    linear-gradient(var(--m),var(--m)) bottom left/var(--l) var(--g) no-repeat,
    linear-gradient(var(--m),var(--m)) bottom left/var(--g) var(--l) no-repeat,
    linear-gradient(var(--m),var(--m)) bottom right/var(--l) var(--g) no-repeat,
    linear-gradient(var(--m),var(--m)) bottom right/var(--g) var(--l) no-repeat;
}
.marcas{position:absolute;inset:clamp(.75rem,3vw,1.75rem);pointer-events:none;z-index:0}

/* Fondos de pantalla completa */
.foto-fondo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}
.velo{position:absolute;inset:0;z-index:-1;background:linear-gradient(to top,rgba(20,25,28,.9) 0%,rgba(20,25,28,.72) 55%,rgba(20,25,28,.3) 100%)}
.plano{
  position:absolute;inset:0;z-index:-2;background-color:var(--grafito);
  background-image:
    linear-gradient(to top right,transparent calc(50% - 1px),rgba(239,194,58,.35) 50%,transparent calc(50% + 1px)),
    linear-gradient(rgba(255,255,255,.055) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.055) 1px,transparent 1px);
  background-size:100% 100%,2rem 2rem,2rem 2rem;
}

/* Portada */
.portada{
  position:relative;isolation:isolate;overflow:hidden;
  display:flex;align-items:flex-end;
  min-height:max(34rem,calc(100vh - 9rem));
  min-height:max(34rem,calc(100svh - 9rem));
  background:var(--grafito);color:#fff;
}
.portada--media{min-height:min(72vh,42rem);min-height:min(72svh,42rem)}
.portada__texto{position:relative;z-index:1;width:100%;max-width:var(--ancho);margin:0 auto;padding:clamp(5rem,12vh,8rem) calc(var(--margen) + .5rem) clamp(3rem,8vh,5rem)}
.titular{margin:0 0 1.25rem;max-width:16ch;font-size:clamp(2.25rem,1.1rem + 5.4vw,6.25rem);font-weight:300;font-stretch:112%;line-height:1.03;letter-spacing:-.025em}
.bajada{margin:0 0 2rem;max-width:34em;font-size:clamp(1.0625rem,1rem + .4vw,1.3rem);line-height:1.55;color:#E7EAEB}
.portada__dato{margin:2.75rem 0 0;padding-top:1rem;max-width:34em;border-top:1px solid rgba(255,255,255,.35);font-family:var(--mono);font-size:1rem;line-height:1.5;color:#DDE2E4}
.titulo-pagina{margin:0;font-size:clamp(2.5rem,1.4rem + 4.4vw,5.25rem);font-weight:300;font-stretch:115%;line-height:1;letter-spacing:-.025em}

/* Secciones */
.seccion{padding:clamp(4rem,10vw,8rem) var(--margen)}
.seccion__in{max-width:var(--ancho);margin:0 auto}
.titulo-seccion{margin:0;font-size:clamp(1.75rem,1.3rem + 1.6vw,2.75rem);font-weight:400;font-stretch:112%;line-height:1.1;letter-spacing:-.015em}

.servicios .seccion__in{display:grid;grid-template-columns:1fr;gap:2rem 4rem}
.lista-servicios{list-style:none;margin:0;padding:0;border-top:1px solid var(--tinta)}
.lista-servicios li{display:grid;gap:.5rem 3rem;padding:1.75rem 0;border-bottom:1px solid var(--linea)}
.lista-servicios h3{margin:0;font-size:1.375rem;font-weight:500;font-stretch:108%;line-height:1.25}
.lista-servicios p{margin:0;max-width:36em;color:var(--gris)}

/* Franja de obra */
.franja{position:relative;isolation:isolate;overflow:hidden;display:flex;align-items:flex-end;min-height:min(88vh,56rem);min-height:min(88svh,56rem);background:var(--grafito);color:#fff}
.franja--plano{min-height:0;display:block}
.franja__in{position:relative;z-index:1;width:100%;max-width:var(--ancho);margin:0 auto;padding:clamp(4rem,9vw,7rem) calc(var(--margen) + .5rem);display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:1.5rem 2rem}
.franja--plano .franja__in{display:block}
.franja--plano .titulo-seccion{margin-bottom:2rem}

.vacios{list-style:none;margin:0 0 2.5rem;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:.75rem}
.vacios li:first-child{grid-column:1/-1}
.vacio{--l:1.25rem;display:grid;place-items:center;aspect-ratio:4/3;padding:1rem;text-align:center;border:1px solid rgba(255,255,255,.22);font-family:var(--mono);font-size:1rem;line-height:1.4;color:#D3D9DB}

/* Galería */
.encabezado{padding:clamp(3rem,8vw,6rem) var(--margen) clamp(2rem,4vw,3rem)}
.obras{list-style:none;margin:0;padding:0 clamp(.5rem,1.5vw,1rem) clamp(4rem,8vw,6rem);display:grid;grid-template-columns:1fr;gap:clamp(.5rem,1.5vw,1rem)}
.obras figure{margin:0;height:100%}
.obras img{width:100%;height:100%;aspect-ratio:4/3;object-fit:cover;background:var(--hormigon)}
.obras--vacias{padding-left:var(--margen);padding-right:var(--margen)}
.obras--vacias .vacio{--m:var(--tinta);height:100%;border-color:var(--linea);color:var(--gris);background-color:var(--hormigon)}

.cierre{background:var(--hormigon)}
.cierre .seccion__in{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:1.5rem 3rem}
.cierre__texto{margin:0;max-width:30em;font-size:clamp(1.25rem,1.05rem + .8vw,1.75rem);font-weight:300;line-height:1.4}

/* Nosotros */
.sobre .seccion__in{display:grid;grid-template-columns:1fr;gap:1.5rem 4rem}
.sobre__firma{margin:0;font-family:var(--mono);font-size:1rem;color:var(--gris)}
.sobre__texto{margin:0;max-width:32em;font-size:clamp(1.25rem,1.05rem + .8vw,1.75rem);font-weight:300;line-height:1.5;white-space:pre-line}
.destacados{list-style:none;margin:3rem 0 0;padding:0;max-width:44rem;border-top:1px solid var(--tinta)}
.destacados li{padding:1.1rem 0;border-bottom:1px solid var(--linea)}
.destacados:empty{display:none}

/* Contacto */
.contacto{position:relative;isolation:isolate;overflow:hidden;background:var(--grafito);color:#fff}
.contacto .seccion__in{position:relative;z-index:1;padding:0 .5rem}
.datos{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(16rem,100%),1fr));gap:2.5rem 3rem;margin:3rem 0 0}
.datos dt{margin:0 0 .5rem;font-family:var(--mono);font-size:1rem;color:var(--gris-claro)}
.datos dd{margin:0;font-size:clamp(1.25rem,1.1rem + .6vw,1.6rem);font-stretch:108%;line-height:1.3;overflow-wrap:anywhere}
.datos .boton{margin-top:1.25rem}
.contacto__accion{margin:3.5rem 0 0}

/* Pie */
.pie{background:var(--tinta);color:#E9ECED;padding:clamp(3rem,7vw,5rem) var(--margen) clamp(2.5rem,5vw,4rem)}
.pie__in{max-width:var(--ancho);margin:0 auto;display:grid;grid-template-columns:1fr;gap:2.5rem 3rem}
.pie__nombre{margin:0;font-size:clamp(1.5rem,1.2rem + 1.2vw,2.25rem);font-weight:300;font-stretch:115%;line-height:1.1;letter-spacing:-.02em;overflow-wrap:break-word}
.pie h2{margin:0 0 .75rem;font-family:var(--mono);font-size:1rem;font-weight:400;color:var(--gris-claro)}
.pie p{margin:0}
.pie ul{list-style:none;margin:0;padding:0}
.pie a{display:inline-flex;align-items:center;min-height:44px;text-underline-offset:.35em;text-decoration-thickness:1px}
.pie a:hover{color:#fff;text-decoration-color:var(--senal)}

/* Barra fija en celular */
.barra{position:fixed;left:0;right:0;bottom:0;z-index:20;display:flex;gap:.5rem;padding:.625rem var(--margen) calc(.625rem + env(safe-area-inset-bottom));background:var(--tinta);border-top:1px solid rgba(255,255,255,.12)}
.barra .boton{flex:1 1 0;min-width:0}

@media (min-width:600px){
  .obras{grid-template-columns:1fr 1fr}
  .obras li:nth-child(3n+1){grid-column:1/-1}
  .obras li:nth-child(3n+1) img{aspect-ratio:16/9;max-height:92vh}
  .vacios{grid-template-columns:repeat(3,1fr)}
  .vacios li:first-child{grid-column:auto}
}
@media (min-width:760px){
  body{padding-bottom:0}
  .barra{display:none}
  .cab nav{width:auto}
  .menu{gap:0 1.75rem}
  .cab .boton{display:inline-flex}
  .pie__in{grid-template-columns:repeat(2,1fr)}
}
@media (min-width:960px){
  .servicios .seccion__in{grid-template-columns:minmax(12rem,1fr) 2.4fr}
  .lista-servicios li{grid-template-columns:1fr 1.3fr}
  .sobre .seccion__in{grid-template-columns:minmax(12rem,1fr) 2.4fr}
  .pie__in{grid-template-columns:1.4fr 1fr 1fr 1fr}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition:none!important;animation:none!important}
}

:root {
  --fondo: #1C1417;
  --capa: #261B1F;
  --capa-alta: #30232A;
  --crema: #F1E8DC;
  --suave: #C9B9AB;
  --bronce: #C9A06A;
  --bronce-claro: #DDBB8B;
  --linea: rgba(201, 160, 106, 0.32);
  --linea-tenue: rgba(241, 232, 220, 0.12);
  --serif: "Italiana", "Didot", "Bodoni 72", Georgia, serif;
  --sans: "Albert Sans", "Helvetica Neue", Arial, sans-serif;
  --ancho: 72rem;
  --margen: clamp(1.25rem, 5vw, 3rem);
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--fondo);
  color: var(--crema);
  font-family: var(--sans);
  font-size: 1.0625rem;
  line-height: 1.65;
  overflow-x: hidden;
  overflow-wrap: break-word;
}

img { display: block; max-width: 100%; }

h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 400;
  margin: 0;
  letter-spacing: 0.01em;
}

p { margin: 0; }

a { color: inherit; }

a:focus-visible {
  outline: 2px solid var(--bronce-claro);
  outline-offset: 4px;
  border-radius: 2px;
}

/* Franja de aviso */
.aviso {
  background: var(--capa-alta);
  border-bottom: 1px solid var(--linea);
  padding: 0.75rem var(--margen);
  text-align: center;
}
.aviso p {
  max-width: var(--ancho);
  margin: 0 auto;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--crema);
}

/* Cabecera */
.cabecera {
  max-width: var(--ancho);
  margin: 0 auto;
  padding: 1.5rem var(--margen);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem 2rem;
  flex-wrap: wrap;
}
.marca {
  font-family: var(--serif);
  font-size: clamp(1.6rem, 4vw, 2rem);
  line-height: 1.1;
  text-decoration: none;
  color: var(--crema);
}
.menu {
  display: flex;
  flex-wrap: wrap;
  gap: 0 1.75rem;
  margin-left: auto;
}
.menu a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 1rem;
  color: var(--suave);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.menu a:hover { color: var(--crema); border-bottom-color: var(--linea); }

/* Botones */
.boton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0.7rem 1.6rem;
  font-family: var(--sans);
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-decoration: none;
  text-align: center;
  color: var(--fondo);
  background: var(--bronce);
  border: 1px solid var(--bronce);
  border-radius: 999px;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}
.boton:hover { background: var(--bronce-claro); border-color: var(--bronce-claro); }
.boton-linea {
  color: var(--crema);
  background: transparent;
  border-color: var(--linea);
  font-weight: 500;
}
.boton-linea:hover {
  background: transparent;
  color: var(--bronce-claro);
  border-color: var(--bronce);
}

/* Portada */
.portada {
  max-width: var(--ancho);
  margin: 0 auto;
  padding: clamp(2.5rem, 8vw, 6rem) var(--margen) clamp(4rem, 10vw, 8rem);
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: clamp(2.5rem, 6vw, 5rem);
  align-items: end;
}
.portada h1 {
  font-size: clamp(2.9rem, 8.5vw, 6.25rem);
  line-height: 1.02;
  max-width: 15ch;
  hyphens: auto;
}
.bajada {
  margin-top: 1.75rem;
  max-width: 34rem;
  font-size: clamp(1.0625rem, 2vw, 1.25rem);
  line-height: 1.6;
  color: var(--suave);
}
.acciones {
  margin-top: 2.5rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.875rem;
}

/* Arco: el motivo de la plantilla */
.portada-arco {
  justify-self: end;
  width: 100%;
  max-width: 24rem;
  animation: aparecer 1.1s cubic-bezier(.2,.7,.2,1) both;
}
.arco {
  margin: 0;
  padding: 0.625rem;
  border: 1px solid var(--linea);
  border-radius: 999px 999px 0 0;
}
.arco img {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  border-radius: 999px 999px 0 0;
  background: var(--capa);
}
.arco-vacio {
  position: relative;
  aspect-ratio: 4 / 5;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 2.5rem 2.25rem 3rem;
  background:
    radial-gradient(120% 70% at 50% 0%, rgba(201, 160, 106, 0.16), transparent 70%),
    var(--capa);
  overflow: hidden;
}
.arco-vacio::before,
.arco-vacio::after {
  content: "";
  position: absolute;
  border: 1px solid var(--linea);
  border-bottom: 0;
  border-radius: 999px 999px 0 0;
  pointer-events: none;
}
.arco-vacio::before { inset: 1.25rem 1.25rem 0; }
.arco-vacio::after { inset: 2.75rem 2.75rem 0; border-color: rgba(201, 160, 106, 0.18); }
.arco-vacio span {
  position: relative;
  font-family: var(--serif);
  font-size: clamp(2.1rem, 7vw, 3.1rem);
  line-height: 1.05;
  text-align: center;
  color: var(--bronce-claro);
  overflow-wrap: anywhere;
}

@keyframes aparecer {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}

/* Secciones */
.seccion {
  max-width: var(--ancho);
  margin: 0 auto;
  padding: clamp(4rem, 10vw, 7.5rem) var(--margen);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 2.2fr);
  gap: 2rem clamp(2rem, 6vw, 5rem);
  border-top: 1px solid var(--linea-tenue);
}
.seccion > h2 {
  font-size: clamp(2.4rem, 5.5vw, 3.6rem);
  line-height: 1.05;
  color: var(--crema);
}

/* Servicios */
.lista-servicios {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
  gap: 3rem 3rem;
}
.lista-servicios h3 {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  font-size: clamp(1.75rem, 3.5vw, 2.1rem);
  line-height: 1.15;
}
.lista-servicios h3::before {
  content: "";
  flex: none;
  width: 0.55rem;
  height: 0.7rem;
  border: 1px solid var(--bronce);
  border-bottom: 0;
  border-radius: 999px 999px 0 0;
  transform: translateY(-0.1rem);
}
.lista-servicios p {
  margin-top: 0.75rem;
  color: var(--suave);
  max-width: 36rem;
}

/* Turnos */
.turnos-fondo {
  background: var(--capa);
  border-top: 1px solid var(--linea);
  border-bottom: 1px solid var(--linea);
}
.turnos-fondo .seccion { border-top: 0; }
.lista-turnos {
  list-style: none;
  margin: 0;
  padding: 0;
}
.lista-turnos li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem 2rem;
  flex-wrap: wrap;
  padding: 1.25rem 0;
  border-bottom: 1px solid var(--linea-tenue);
}
.lista-turnos li:first-child { padding-top: 0; }
.turno-nombre {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 1.85rem);
  line-height: 1.2;
}
.turnos-otros {
  margin-top: 2.25rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.875rem;
}

/* Nosotros */
.nosotros-cuerpo {
  display: flex;
  flex-wrap: wrap;
  gap: 3rem;
  align-items: flex-start;
}
.nosotros-texto { flex: 1 1 22rem; min-width: 0; }
.sobre {
  font-size: clamp(1.125rem, 2.2vw, 1.3rem);
  line-height: 1.7;
  max-width: 38rem;
}
.destacados {
  list-style: none;
  margin: 2.5rem 0 0;
  padding: 0;
  display: grid;
  gap: 1rem;
}
.destacados li {
  padding-left: 1.25rem;
  border-left: 1px solid var(--bronce);
  color: var(--suave);
  max-width: 34rem;
}
.nosotros-fotos {
  flex: 1 1 18rem;
  min-width: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  align-items: end;
}
.nosotros-fotos .arco:last-child { margin-bottom: 2.5rem; }

/* Cómo llegar */
.direccion {
  font-family: var(--serif);
  font-size: clamp(1.9rem, 4.5vw, 2.8rem);
  line-height: 1.15;
  max-width: 22ch;
}
.llegar-acciones {
  margin-top: 2rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.875rem;
}

/* Pie */
.pie {
  border-top: 1px solid var(--linea);
  padding: 3.5rem var(--margen) 3rem;
}
.pie-dentro {
  max-width: var(--ancho);
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2rem;
}
.pie-marca {
  font-family: var(--serif);
  font-size: 2rem;
  line-height: 1.1;
}
.pie-datos {
  display: grid;
  gap: 0.25rem;
  color: var(--suave);
}
.pie-datos a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--crema);
  text-decoration-color: var(--linea);
  text-underline-offset: 4px;
}
.pie-datos a:hover { color: var(--bronce-claro); }

/* Barra fija en celular */
.barra-movil { display: none; }

@media (max-width: 860px) {
  .portada { grid-template-columns: 1fr; align-items: start; }
  .portada-arco { justify-self: start; max-width: 20rem; }
  .seccion { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  body { padding-bottom: 5.5rem; }
  .cabecera { padding-top: 1.25rem; padding-bottom: 0.5rem; }
  .boton-cabecera { display: none; }
  .menu { margin-left: 0; width: 100%; gap: 0 1.25rem; }
  .acciones .boton { flex: 1 1 100%; }
  .portada-arco { max-width: 82%; }
  .nosotros-fotos .arco:last-child { margin-bottom: 1.5rem; }
  .lista-turnos .boton { flex: 1 1 100%; }
  .barra-movil {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 20;
    display: flex;
    gap: 0.625rem;
    padding: 0.75rem var(--margen) calc(0.75rem + env(safe-area-inset-bottom));
    background: var(--fondo);
    border-top: 1px solid var(--linea);
  }
  .barra-movil .boton { flex: 1 1 auto; }
  .barra-movil .boton-linea { flex: 0 0 auto; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .portada-arco { animation: none; }
  .boton, .menu a { transition: none; }
}

:root{
  --salvia-claro:#EEF0E6;
  --arena:#E6DAC4;
  --salvia:#9FB291;
  --musgo:#2F4A3A;
  --tinta:#24302A;
  --tinta-suave:#46564B;
  --ocre:#A86F2A;
  --crema:#F6F1E6;
  --r-piedra:46% 54% 52% 48% / 58% 44% 56% 42%;
  --r-piedra-2:62% 38% 44% 56% / 48% 60% 40% 52%;
  --r-piedra-3:40% 60% 58% 42% / 52% 46% 54% 48%;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  font-family:"Alegreya Sans",system-ui,sans-serif;
  font-size:1.125rem;
  line-height:1.6;
  color:var(--tinta);
  background-color:var(--salvia-claro);
  background-image:
    radial-gradient(rgba(47,74,58,.045) 1px,transparent 1.4px),
    radial-gradient(rgba(168,111,42,.04) 1px,transparent 1.4px);
  background-size:7px 7px,11px 11px;
  background-position:0 0,3px 5px;
  overflow-x:hidden;
}
img{max-width:100%;display:block;height:auto}
a{color:var(--musgo);text-underline-offset:.18em;text-decoration-thickness:1px}
a:hover{text-decoration-thickness:2px}
:focus-visible{outline:3px solid var(--ocre);outline-offset:3px;border-radius:6px}
h1,h2,h3{font-family:"Alegreya",Georgia,serif;font-weight:500;color:var(--musgo);line-height:1.12;margin:0}
p{margin:0}
.wrap{width:100%;max-width:1120px;margin-inline:auto;padding-inline:20px}

/* Franja de aviso */
.aviso{background:var(--musgo);color:var(--crema);font-size:1rem;line-height:1.45;padding:.7rem 0;text-align:center}
.aviso p{max-width:68ch;margin-inline:auto}

/* Encabezado */
.cabecera{padding:1.1rem 0 .6rem}
.cabecera .wrap{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.6rem 1.5rem}
.marca{display:inline-flex;align-items:center;gap:.65rem;font-family:"Alegreya",Georgia,serif;font-size:1.45rem;font-weight:700;color:var(--musgo);text-decoration:none;min-height:44px}
.marca::before{content:"";width:22px;height:26px;background:var(--salvia);border-radius:var(--r-piedra);box-shadow:8px 6px 0 -3px var(--arena)}
.menu{display:flex;flex-wrap:wrap;gap:.1rem .4rem;margin:0;padding:0;list-style:none}
.menu a{display:inline-flex;align-items:center;min-height:44px;padding:0 .7rem;border-radius:999px;color:var(--tinta);text-decoration:none;font-size:1.05rem}
.menu a:hover{background:rgba(159,178,145,.35)}
.menu a[aria-current="page"]{background:var(--arena);color:var(--musgo);font-weight:700}
.cabecera .boton{display:none}

/* Botones */
.boton{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:.6rem 1.5rem;border-radius:999px;background:var(--musgo);color:var(--crema);font-weight:700;font-size:1.05rem;text-decoration:none;border:2px solid var(--musgo);line-height:1.2;text-align:center}
.boton:hover{background:#243A2D;border-color:#243A2D}
.boton-suave{background:transparent;color:var(--musgo)}
.boton-suave:hover{background:rgba(159,178,145,.3);border-color:var(--musgo)}

/* Hero */
.hero{padding:2rem 0 3.5rem}
.hero .wrap{display:grid;gap:2.5rem;align-items:center}
.hero h1{font-size:clamp(2.3rem,7vw,4.1rem);letter-spacing:-.01em;max-width:16ch}
.hero .bajada{margin-top:1.1rem;font-size:1.2rem;color:var(--tinta-suave);max-width:46ch}
.hero .acciones{display:flex;flex-wrap:wrap;gap:.75rem;margin-top:1.75rem}
.hero-forma{position:relative;justify-self:center;width:min(100%,440px);animation:asentar 1s cubic-bezier(.2,.7,.2,1) both}
.hero-forma::before{content:"";position:absolute;width:42%;aspect-ratio:1;right:-4%;bottom:-6%;background:var(--salvia);border-radius:var(--r-piedra-2);z-index:0}
.hero-forma::after{content:"";position:absolute;width:20%;aspect-ratio:1;left:2%;top:-3%;background:var(--ocre);opacity:.85;border-radius:var(--r-piedra-3);z-index:0}
.hero-foto{position:relative;z-index:1;width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:var(--r-piedra)}

/* Versión sin fotos: piedras tipográficas */
.piedras{position:relative;z-index:1;width:100%;aspect-ratio:1/1.05}
.piedra{position:absolute;display:flex;align-items:center;justify-content:center;text-align:center;padding:12%}
.piedra-grande{inset:6% 10% 18% 0;background:var(--musgo);border-radius:var(--r-piedra)}
.piedra-grande span{font-family:"Alegreya",Georgia,serif;font-weight:700;font-size:clamp(1.6rem,6vw,2.5rem);line-height:1.1;color:var(--crema);overflow-wrap:anywhere}
.piedra-media{width:44%;aspect-ratio:1;right:0;bottom:0;background:var(--arena);border-radius:var(--r-piedra-2)}
.piedra-chica{width:18%;aspect-ratio:1;right:16%;top:0;background:var(--salvia);border-radius:var(--r-piedra-3)}

@keyframes asentar{from{opacity:0;transform:translateY(18px) rotate(-3deg) scale(.97)}to{opacity:1;transform:none}}

/* Destacados */
.destacados{display:flex;flex-wrap:wrap;gap:.6rem;margin:2rem 0 0;padding:0;list-style:none}
.destacados li{background:var(--crema);border:1px solid rgba(47,74,58,.18);border-radius:var(--r-piedra-2);padding:.55rem 1.1rem;font-size:1rem;color:var(--tinta)}

/* Secciones */
.seccion{padding:3.5rem 0}
.seccion-arena{background:var(--arena);border-radius:48px 48px 0 0 / 36px 36px 0 0}
.seccion h2{font-size:clamp(1.9rem,5vw,2.75rem);margin-bottom:1.5rem}
.cabeza-seccion{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:.5rem 1.5rem;margin-bottom:1.5rem}
.cabeza-seccion h2{margin-bottom:0}

/* Servicios (inicio) */
.servicios{display:grid;gap:0;margin:0;padding:0;list-style:none}
.servicio{display:grid;grid-template-columns:auto 1fr;gap:.25rem 1rem;padding:1.35rem 0;border-top:1px solid rgba(47,74,58,.2)}
.servicio:last-child{border-bottom:1px solid rgba(47,74,58,.2)}
.servicio::before{content:"";grid-row:1 / span 2;width:16px;height:18px;margin-top:.5rem;background:var(--salvia);border-radius:var(--r-piedra)}
.servicio h3{font-size:1.45rem}
.servicio p{color:var(--tinta-suave);max-width:60ch}

/* Sobre */
.sobre{display:grid;gap:2rem;align-items:center}
.sobre-texto p{font-size:1.2rem;line-height:1.7;max-width:58ch}
.sobre-texto .boton{margin-top:1.5rem}
.sobre-foto{width:100%;aspect-ratio:5/4;object-fit:cover;border-radius:var(--r-piedra-2)}
.sobre-forma{width:100%;max-width:360px;aspect-ratio:5/4;background:var(--salvia);border-radius:var(--r-piedra-2);display:flex;align-items:center;justify-content:center;padding:2rem;text-align:center;font-family:"Alegreya",Georgia,serif;font-size:1.6rem;color:var(--tinta)}

/* Cómo llegar */
.llegar{background:var(--crema);border-radius:var(--r-piedra-3);padding:2.25rem 1.75rem;display:grid;gap:1.25rem;justify-items:start}
.llegar .direccion{font-family:"Alegreya",Georgia,serif;font-size:1.5rem;color:var(--musgo);line-height:1.3}

/* Turnos */
.intro-pagina{padding:2rem 0 1rem}
.intro-pagina h1{font-size:clamp(2.2rem,6vw,3.4rem)}
.intro-pagina p{margin-top:.9rem;font-size:1.2rem;color:var(--tinta-suave);max-width:52ch}
.turnos{display:grid;gap:1rem;margin:0;padding:0;list-style:none}
.turno{background:var(--crema);border:1px solid rgba(47,74,58,.14);border-radius:28px 36px 30px 40px / 34px 28px 38px 30px;padding:1.5rem 1.4rem;display:grid;gap:.6rem 1.5rem;align-items:center}
.turno h2{font-size:1.5rem;margin:0}
.turno p{color:var(--tinta-suave);max-width:58ch}
.turno .boton{justify-self:start;margin-top:.4rem}

/* Galería */
.galeria{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem;margin:0;padding:0;list-style:none}
.galeria img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:28px}
.galeria li:nth-child(3n+1) img{border-radius:var(--r-piedra)}

/* Contacto */
.vias{display:grid;gap:1rem;margin:0;padding:0;list-style:none}
.via{background:var(--crema);border-radius:var(--r-piedra-3);padding:1.75rem 1.5rem;display:grid;gap:.75rem;justify-items:start}
.via h2{font-size:1.5rem;margin:0}
.via p{font-size:1.15rem}

/* Pie */
.pie{background:var(--musgo);color:var(--crema);padding:3rem 0 2.5rem;margin-top:3rem;border-radius:48px 48px 0 0 / 36px 36px 0 0}
.pie .wrap{display:grid;gap:2rem}
.pie h2{color:var(--crema);font-size:1.8rem;margin-bottom:.75rem}
.pie h3{color:var(--crema);font-size:1.25rem;margin-bottom:.5rem}
.pie p{color:#E7E2D5}
.pie a{color:var(--crema)}
.pie-links{list-style:none;margin:0;padding:0;display:grid;gap:.15rem}
.pie-links a{display:inline-flex;align-items:center;min-height:44px}
.pie .boton{background:var(--crema);color:var(--musgo);border-color:var(--crema);margin-top:1rem}
.pie .boton:hover{background:#fff;border-color:#fff}

/* Barra fija celular */
.barra{position:fixed;left:0;right:0;bottom:0;z-index:20;display:flex;gap:.5rem;padding:.6rem 12px calc(.6rem + env(safe-area-inset-bottom));background:rgba(246,241,230,.97);border-top:1px solid rgba(47,74,58,.2)}
.barra .boton{flex:1;min-height:50px;padding-inline:.75rem}
body{padding-bottom:84px}

@media (min-width:700px){
  .galeria{grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
  .vias{grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}
  .turno{grid-template-columns:1fr auto;padding:1.75rem 2rem}
  .turno .boton{grid-column:2;grid-row:1 / span 2;margin-top:0}
  .pie .wrap{grid-template-columns:1.3fr 1fr 1fr}
}
@media (min-width:900px){
  body{padding-bottom:0}
  .barra{display:none}
  .cabecera .boton{display:inline-flex}
  .hero{padding:3.5rem 0 5rem}
  .hero .wrap{grid-template-columns:1.15fr .85fr;gap:4rem}
  .hero-forma{justify-self:end}
  .seccion{padding:5rem 0}
  .sobre{grid-template-columns:1.2fr .8fr;gap:4rem}
  .llegar{grid-template-columns:1fr auto;align-items:center;padding:2.75rem 3rem}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
}

:root{
  --negro:#000;
  --blanco:#fff;
  --senal:#FFC629;
  --gris:#4a4a4a;
  --linea:#e2e2e2;
  --g:16px;
  --max:1240px;
  --cols:4;
}
@media (min-width:900px){
  :root{--g:32px;--cols:12;}
}
*,*::before,*::after{box-sizing:border-box;}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;}
body{
  margin:0;
  background:var(--blanco);
  color:var(--negro);
  font-family:"Schibsted Grotesk",Arial,sans-serif;
  font-size:1.0625rem;
  line-height:1.5;
  overflow-x:hidden;
  padding-bottom:84px;
}
@media (min-width:900px){body{padding-bottom:0;}}
body::before{
  content:"";
  position:fixed;
  top:0;bottom:0;left:0;right:0;
  margin-inline:auto;
  width:min(100% - 2*var(--g),var(--max));
  background-image:repeating-linear-gradient(90deg,var(--linea) 0 1px,transparent 1px calc(100% / var(--cols)));
  border-right:1px solid var(--linea);
  z-index:-1;
  pointer-events:none;
}
img{display:block;max-width:100%;}
a{color:inherit;}
h1,h2,h3,p,ul,figure{margin:0;}
ul{padding:0;list-style:none;}
:focus-visible{outline:3px solid var(--negro);outline-offset:3px;}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto;}
  *,*::before,*::after{animation:none !important;transition:none !important;}
}

/* Grilla */
.w{width:min(100% - 2*var(--g),var(--max));margin-inline:auto;}
.g,.g9{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));}
@media (min-width:900px){
  .g{grid-template-columns:repeat(12,minmax(0,1fr));}
  .g9{grid-template-columns:repeat(9,minmax(0,1fr));}
}
:where(.g,.g9)>*{padding-inline:12px;min-width:0;}

/* Aviso */
.aviso{background:var(--negro);color:var(--blanco);}
.aviso p{padding-block:12px;font-size:1rem;font-weight:500;grid-column:1/-1;}
.aviso :focus-visible{outline-color:var(--senal);}

/* Encabezado */
.cab{padding-block:16px;align-items:center;row-gap:8px;border-bottom:2px solid var(--negro);}
.marca{grid-column:1/-1;font-weight:800;font-size:1.25rem;letter-spacing:-.01em;text-decoration:none;line-height:1.2;}
.menu{grid-column:1/-1;display:flex;flex-wrap:wrap;column-gap:20px;}
.menu a{display:inline-flex;align-items:center;min-height:44px;font-size:1rem;font-weight:500;text-decoration:none;}
.menu a:hover{text-decoration:underline;text-underline-offset:4px;text-decoration-thickness:2px;}
.cab-cta{display:none;}
@media (min-width:900px){
  .marca{grid-column:1/5;}
  .menu{grid-column:5/10;column-gap:28px;}
  .cab-cta{display:block;grid-column:10/13;justify-self:end;}
}

/* Botones */
.btn{
  display:inline-flex;align-items:center;justify-content:center;
  min-height:48px;padding:10px 22px;
  font:inherit;font-size:1rem;font-weight:700;line-height:1.2;
  text-decoration:none;border:2px solid var(--negro);
  transition:background-color .15s,color .15s;
}
.btn-acc{background:var(--senal);color:var(--negro);}
.btn-acc:hover{background:var(--negro);color:var(--senal);}
.btn-lin{background:var(--blanco);color:var(--negro);}
.btn-lin:hover{background:var(--negro);color:var(--blanco);}

/* Portada */
.hero{padding-block:48px 56px;row-gap:24px;}
.hero-t{
  grid-column:1/-1;
  font-weight:800;
  font-size:clamp(2.75rem,7.2vw + .5rem,6.5rem);
  line-height:.95;
  letter-spacing:-.04em;
  overflow-wrap:break-word;
  hyphens:auto;
}
.hero-b{grid-column:1/-1;font-size:1.25rem;line-height:1.45;max-width:34ch;}
.hero-cta{grid-column:1/-1;}
.hero-f{grid-column:1/-1;padding-inline:0;}
.hero-f img{width:100%;aspect-ratio:4/3;object-fit:cover;animation:aparecer .8s cubic-bezier(.2,.7,.2,1) both;}
.hero-block{
  grid-column:1/-1;
  margin-inline:12px;
  display:flex;flex-direction:column;justify-content:space-between;gap:32px;
  min-height:240px;padding:24px;
  background:var(--senal);color:var(--negro);
  text-decoration:none;
  border:2px solid var(--negro);
  animation:aparecer .8s cubic-bezier(.2,.7,.2,1) both;
  transition:background-color .15s,color .15s;
}
.hero-block:hover{background:var(--negro);color:var(--senal);}
.hero-block .gr{font-weight:800;font-size:clamp(2rem,3vw + 1rem,3.25rem);line-height:1;letter-spacing:-.03em;}
.hero-block .ch{font-size:1.125rem;font-weight:500;}
@keyframes aparecer{from{clip-path:inset(100% 0 0 0);}to{clip-path:inset(0 0 0 0);}}
@media (min-width:900px){
  .hero{padding-block:88px 104px;grid-template-rows:auto auto 1fr;row-gap:32px;}
  .hero-t{grid-column:1/9;grid-row:1;}
  .hero-b{grid-column:1/7;grid-row:2;}
  .hero-cta{grid-column:1/7;grid-row:3;align-self:start;}
  .hero-f{grid-column:9/13;grid-row:1/4;}
  .hero-f img{aspect-ratio:3/4;height:100%;}
  .hero-block{grid-column:9/13;grid-row:1/4;min-height:420px;padding:28px;}
}

/* Destacados */
.dest{padding-bottom:56px;row-gap:24px;}
.dest li{grid-column:1/-1;}
.dest p{border-top:2px solid var(--negro);padding-top:14px;font-size:1.125rem;font-weight:500;line-height:1.4;max-width:30ch;}
@media (min-width:900px){
  .dest{padding-bottom:96px;}
  .dest li{grid-column:span 4;}
}

/* Secciones */
.sec{padding-block:24px 64px;border-top:2px solid var(--negro);row-gap:24px;scroll-margin-top:12px;}
.sec-h{grid-column:1/-1;font-size:1.25rem;font-weight:700;letter-spacing:-.01em;line-height:1.3;}
.sec-b{grid-column:1/-1;padding-inline:0;align-content:start;}
@media (min-width:900px){
  .sec{padding-block:32px 112px;}
  .sec-h{grid-column:1/4;}
  .sec-b{grid-column:4/13;}
}

/* Servicios */
.row{grid-column:1/-1;padding-inline:0;padding-block:20px 28px;border-top:1px solid var(--negro);row-gap:12px;align-items:start;}
.row:first-child{border-top:0;padding-top:0;}
.row h3{grid-column:1/-1;font-size:clamp(1.5rem,1.4vw + 1rem,2.125rem);font-weight:700;line-height:1.1;letter-spacing:-.025em;}
.row p{grid-column:1/-1;color:var(--gris);max-width:44ch;}
.row .acc{grid-column:1/-1;}
@media (min-width:900px){
  .row{padding-block:24px 32px;}
  .row h3{grid-column:1/5;}
  .row p{grid-column:5/8;}
  .row .acc{grid-column:8/10;justify-self:end;}
}

/* Nosotros */
.sobre{grid-column:1/-1;font-size:clamp(1.25rem,1vw + 1rem,1.75rem);font-weight:500;line-height:1.4;letter-spacing:-.01em;max-width:36ch;}
.gal{grid-column:1/-1;padding-inline:0;margin-top:40px;row-gap:24px;}
.gal li{grid-column:span 2;}
.gal img{width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;}
@media (min-width:900px){
  .sobre{grid-column:1/8;}
  .gal{margin-top:64px;}
  .gal li{grid-column:span 3;}
}

/* Cómo llegar y turno */
.dir{grid-column:1/-1;font-size:clamp(1.75rem,2.4vw + 1rem,3rem);font-weight:700;line-height:1.1;letter-spacing:-.03em;max-width:20ch;}
.acciones{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:12px;margin-top:28px;}
.tel{grid-column:1/-1;font-size:clamp(1.75rem,2.4vw + 1rem,3rem);font-weight:700;line-height:1.1;letter-spacing:-.03em;}
.tel a{text-decoration:none;}
.tel a:hover{text-decoration:underline;text-decoration-thickness:3px;text-underline-offset:6px;}
@media (min-width:900px){
  .dir,.tel{grid-column:1/8;}
  .acciones{grid-column:1/-1;}
}

/* Pie */
.pie{background:var(--negro);color:var(--blanco);}
.pie :focus-visible{outline-color:var(--senal);}
.pie-in{padding-block:40px 48px;row-gap:24px;}
.pie-n{grid-column:1/-1;font-weight:800;font-size:1.5rem;letter-spacing:-.02em;line-height:1.2;}
.pie-d{grid-column:1/-1;font-size:1rem;}
.pie-d a{display:inline-flex;align-items:center;min-height:44px;text-underline-offset:4px;}
@media (min-width:900px){
  .pie-in{padding-block:56px 64px;}
  .pie-n{grid-column:1/5;}
  .pie-d{grid-column:span 4;}
}

/* Barra fija en celular */
.barra{
  position:fixed;left:0;right:0;bottom:0;z-index:10;
  display:flex;gap:8px;
  padding:12px var(--g) calc(12px + env(safe-area-inset-bottom));
  background:var(--blanco);border-top:2px solid var(--negro);
}
.barra .btn{flex:1;}
.barra .btn-lin{flex:0 0 auto;}
@media (min-width:900px){.barra{display:none;}}

:root{
  --papel:#EBE5DA;
  --papel-claro:#F6F2EB;
  --tinta:#26201C;
  --ceniza:#5A534C;
  --violin:#55263B;
  --violin-osc:#3D1A2A;
  --linea:rgba(38,32,28,.22);
  --miel:#C99A5B;
  --cobrizo:#A4532E;
  --caoba:#6E2A22;
  --chocolate:#4A3026;
  --gris-ceniza:#8E8478;
  --negro:#2B2A2E;
  --serif:"Gloock",Georgia,"Times New Roman",serif;
  --sans:"Hanken Grotesk",system-ui,-apple-system,"Segoe UI",sans-serif;
  --ancho:72rem;
  --margen:clamp(1.25rem,5vw,3rem);
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--papel);color:var(--tinta);font-family:var(--sans);font-size:1.125rem;line-height:1.6;overflow-x:hidden}
img{max-width:100%;display:block}
h1,h2,h3{font-family:var(--serif);font-weight:400;margin:0;overflow-wrap:break-word}
p{margin:0}
a{color:inherit}
:focus-visible{outline:3px solid var(--violin);outline-offset:3px;border-radius:2px}

.salto{position:absolute;left:-999px;top:0;z-index:50;background:var(--tinta);color:var(--papel-claro);padding:.75rem 1rem;font-size:1rem}
.salto:focus{left:1rem;top:1rem}

.ancho{max-width:var(--ancho);margin-inline:auto;padding-inline:var(--margen)}

/* Aviso */
.aviso{background:var(--tinta);color:var(--papel-claro);font-size:1rem;line-height:1.45;text-align:center;padding:.7rem var(--margen)}
.aviso p{max-width:60rem;margin-inline:auto}

/* Cabecera */
.cabecera{border-bottom:1px solid var(--linea)}
.cabecera__in{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.25rem 2rem;padding-block:1rem}
.marca{font-family:var(--serif);font-size:clamp(1.5rem,3vw,1.85rem);line-height:1.1;text-decoration:none;color:var(--tinta);min-height:44px;display:inline-flex;align-items:center}
.menu{display:flex;flex-wrap:wrap;gap:0 1.4rem;flex-basis:100%}
.menu a{font-size:1rem;font-weight:500;text-decoration:none;color:var(--tinta);min-height:44px;display:inline-flex;align-items:center;border-bottom:2px solid transparent}
.menu a:hover{border-bottom-color:var(--linea)}
.menu a[aria-current="page"]{border-bottom-color:var(--violin)}
.cabecera__cta{display:none}

/* Botones y enlaces */
.boton{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:.6rem 1.6rem;border-radius:999px;background:var(--violin);color:var(--papel-claro);font-family:var(--sans);font-size:1.05rem;font-weight:600;line-height:1.2;text-align:center;text-decoration:none;border:1.5px solid var(--violin);transition:background-color .2s ease}
.boton:hover{background:var(--violin-osc);border-color:var(--violin-osc)}
.boton--borde{background:transparent;color:var(--tinta);border-color:var(--tinta)}
.boton--borde:hover{background:var(--tinta);color:var(--papel-claro);border-color:var(--tinta)}
.enlace{display:inline-flex;align-items:center;min-height:44px;color:var(--violin);font-weight:600;text-decoration:underline;text-decoration-thickness:1.5px;text-underline-offset:.3em}
.enlace:hover{text-decoration-thickness:2.5px}
.acciones{display:flex;flex-wrap:wrap;align-items:center;gap:.75rem 1.5rem;margin-top:2rem}

/* Mechones: la carta de colores */
.mechones{display:flex;align-items:flex-start;gap:.4rem}
.mechon{position:relative;flex:1 1 0;min-width:0;height:100%;background-color:var(--c,var(--caoba));background-image:repeating-linear-gradient(90deg,rgba(255,255,255,.10) 0 1px,transparent 1px 4px),linear-gradient(180deg,rgba(255,255,255,.16),rgba(0,0,0,.24));border-radius:2px 2px 46% 46%/2px 2px 12% 12%}
.mechon::before{content:"";position:absolute;left:-2px;right:-2px;top:0;height:.7rem;background:rgba(38,32,28,.55);border-radius:2px}
.mechon:nth-child(7n+1){--c:var(--miel)}
.mechon:nth-child(7n+2){--c:var(--cobrizo)}
.mechon:nth-child(7n+3){--c:var(--caoba)}
.mechon:nth-child(7n+4){--c:var(--chocolate)}
.mechon:nth-child(7n+5){--c:var(--violin)}
.mechon:nth-child(7n+6){--c:var(--gris-ceniza)}
.mechon:nth-child(7n+7){--c:var(--negro)}
.mechones--grande{height:clamp(10rem,32vw,24rem)}
.mechones--grande .mechon:nth-child(2){height:86%}
.mechones--grande .mechon:nth-child(3){height:96%}
.mechones--grande .mechon:nth-child(4){height:78%}
.mechones--grande .mechon:nth-child(5){height:92%}
.mechones--grande .mechon:nth-child(6){height:82%}
.mechones--grande .mechon:nth-child(7){height:98%}
.mechones--grande .mechon,.mechones--sobre .mechon{transform-origin:top center;animation:caer .9s cubic-bezier(.2,.7,.2,1) both}
.mechones--grande .mechon:nth-child(2),.mechones--sobre .mechon:nth-child(2){animation-delay:.06s}
.mechones--grande .mechon:nth-child(3),.mechones--sobre .mechon:nth-child(3){animation-delay:.12s}
.mechones--grande .mechon:nth-child(4),.mechones--sobre .mechon:nth-child(4){animation-delay:.18s}
.mechones--grande .mechon:nth-child(5),.mechones--sobre .mechon:nth-child(5){animation-delay:.24s}
.mechones--grande .mechon:nth-child(6),.mechones--sobre .mechon:nth-child(6){animation-delay:.30s}
.mechones--grande .mechon:nth-child(7),.mechones--sobre .mechon:nth-child(7){animation-delay:.36s}
@keyframes caer{from{transform:scaleY(0)}to{transform:scaleY(1)}}
.mechones--sobre{position:absolute;left:1rem;bottom:-2.5rem;width:min(15rem,62%);height:5.5rem;background:var(--papel);padding:.6rem .6rem 0}
.mechones--pie{width:11rem;height:3.25rem;margin-top:1.25rem;gap:.3rem}
.mechones--vacio{height:clamp(8rem,22vw,13rem);max-width:28rem;margin-bottom:2rem}

/* Portada */
.portada{padding-block:clamp(2.75rem,8vw,6.5rem) clamp(3.5rem,8vw,6.5rem)}
.portada__in{display:grid;gap:2.5rem}
.titular{font-size:clamp(2.75rem,7.6vw,6.25rem);line-height:1.02;letter-spacing:-.015em;max-width:15ch;text-wrap:balance}
.bajada{font-size:1.25rem;line-height:1.55;color:var(--ceniza);max-width:36ch;margin-top:1.5rem}
.portada__foto{margin:0 0 2.5rem;position:relative}
.portada__foto img{width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;background:var(--papel-claro)}

/* Secciones */
.seccion{border-top:1px solid var(--linea);padding-block:clamp(3.5rem,8vw,6.5rem)}
.seccion__cabeza{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:.5rem 2rem}
.seccion__titulo{font-size:clamp(2.1rem,4.6vw,3.25rem);line-height:1.05;letter-spacing:-.01em}

/* Índice de servicios */
.indice{list-style:none;margin:2.25rem 0 0;padding:0;border-bottom:1px solid var(--linea)}
.indice__fila{display:grid;gap:.5rem;padding-block:1.6rem;border-top:1px solid var(--linea)}
.indice__titulo{font-size:clamp(1.6rem,3vw,2.1rem);line-height:1.1}
.indice__texto{color:var(--ceniza);max-width:58ch}
.indice__fila .boton{justify-self:start;margin-top:.75rem}

/* Nosotros */
.nosotros{display:grid;gap:3rem;margin-top:2.25rem}
.sobre{font-size:1.25rem;line-height:1.6;max-width:40ch}
.destacados{list-style:none;margin:2.25rem 0 0;padding:0;max-width:40rem}
.destacados li{position:relative;padding:1rem 0 1rem 2.25rem;border-top:1px solid var(--linea)}
.destacados li::before{content:"";position:absolute;left:0;top:1.2rem;width:1.1rem;height:1.5rem;background:var(--caoba);border-radius:2px 2px 46% 46%/2px 2px 18% 18%}
.destacados li:nth-child(4n+1)::before{background:var(--miel)}
.destacados li:nth-child(4n+2)::before{background:var(--cobrizo)}
.destacados li:nth-child(4n+3)::before{background:var(--violin)}
.destacados li:nth-child(4n+4)::before{background:var(--chocolate)}
.nosotros__foto{margin:0}
.nosotros__foto img{width:100%;height:auto;aspect-ratio:3/4;object-fit:cover}
.tarjeta-nombre{background:var(--violin);color:var(--papel-claro);min-height:18rem;padding:2.25rem;display:flex;flex-direction:column;justify-content:space-between;gap:2rem}
.tarjeta-nombre p{font-family:var(--serif);font-size:clamp(2.2rem,5vw,3.4rem);line-height:1.04;overflow-wrap:anywhere}
.tarjeta-nombre .mechones{height:4rem;max-width:12rem}

/* Galería */
.grilla{list-style:none;margin:2.25rem 0 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}
.grilla img{width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;background:var(--papel-claro)}
.grilla--adelanto li:nth-child(n+3){display:none}
.vacio{max-width:40rem}
.vacio p{font-size:1.25rem;color:var(--ceniza);margin-bottom:1.75rem}

/* Cómo llegar y turno */
.cierre{display:grid;gap:2.5rem;margin-top:2.25rem}
.direccion{font-family:var(--serif);font-size:clamp(1.75rem,4vw,2.75rem);line-height:1.12;margin-bottom:1rem;overflow-wrap:break-word}
.dato{margin-top:.5rem}
.dato a{font-weight:600;color:var(--tinta);text-underline-offset:.3em;display:inline-flex;align-items:center;min-height:44px}
.caja-turno{background:var(--papel-claro);border:1px solid var(--linea);padding:clamp(1.75rem,4vw,2.75rem)}
.caja-turno h2,.caja-turno h3{font-size:clamp(1.9rem,4vw,2.6rem);line-height:1.05;margin-bottom:1.5rem}

/* Cabeza de páginas internas */
.cabeza-pagina{padding-block:clamp(2.75rem,7vw,5.5rem) clamp(1.5rem,4vw,2.5rem)}
.titulo-pagina{font-size:clamp(2.75rem,8vw,5.5rem);line-height:1.02;letter-spacing:-.015em}
.cabeza-pagina .bajada{margin-top:1.25rem}
.seccion--pegada{border-top:0;padding-top:0}

/* Pie */
.pie{background:var(--tinta);color:var(--papel);padding-block:3.5rem 2.5rem}
.pie__in{display:grid;gap:2.25rem}
.pie__nombre{font-family:var(--serif);font-size:2rem;line-height:1.1;overflow-wrap:anywhere}
.pie__titulo{font-family:var(--sans);font-size:1rem;font-weight:600;color:#D4CBBD;margin-bottom:.5rem}
.pie__col p{color:var(--papel)}
.pie a{color:var(--papel);text-underline-offset:.3em;display:inline-flex;align-items:center;min-height:44px}
.pie a:focus-visible{outline-color:var(--papel-claro)}
.pie__lista{list-style:none;margin:0;padding:0}

/* Barra fija en celular */
.barra-movil{position:fixed;left:0;right:0;bottom:0;z-index:20;display:flex;gap:.6rem;padding:.7rem var(--margen) calc(.7rem + env(safe-area-inset-bottom));background:rgba(235,229,218,.97);border-top:1px solid var(--linea)}
.barra-movil .boton{flex:1 1 0}
body{padding-bottom:5.5rem}

@media (min-width:760px){
  .grilla{grid-template-columns:repeat(3,minmax(0,1fr));gap:1.25rem}
  .grilla--adelanto li:nth-child(3){display:block}
  .indice__fila{grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:2.5rem;align-items:baseline}
  .indice--turnos .indice__fila{grid-template-columns:minmax(0,4fr) minmax(0,6fr) auto;align-items:center}
  .indice--turnos .indice__fila .boton{margin-top:0}
  .cierre{grid-template-columns:1fr 1fr;gap:4rem;align-items:start}
  .pie__in{grid-template-columns:1.4fr 1fr 1fr 1fr}
}
@media (min-width:900px){
  body{padding-bottom:0}
  .barra-movil{display:none}
  .menu{flex-basis:auto;margin-left:auto}
  .cabecera__cta{display:inline-flex;min-height:44px;padding-inline:1.25rem;font-size:1rem}
  .portada--foto .portada__in{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:4.5rem;align-items:center}
  .portada--tipo .portada__in{grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:4rem;align-items:end}
  .nosotros{grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:4.5rem;align-items:start}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
}

:root {
  --tinta: #1B1F3A;
  --tinta-2: #2A2F55;
  --papel: #EEF0F5;
  --azafran: #F4C430;
  --niebla: #B9BEDB;
  --foco: #F4C430;
  --ancho: 84rem;
  --margen: 1.25rem;
}

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

body {
  margin: 0;
  font-family: "Archivo", system-ui, sans-serif;
  font-size: 1.0625rem;
  line-height: 1.55;
  color: var(--papel);
  background: var(--tinta);
  overflow-x: clip;
  padding-bottom: calc(76px + env(safe-area-inset-bottom));
}

img { display: block; max-width: 100%; }

a { color: inherit; }

:focus-visible {
  outline: 3px solid var(--foco);
  outline-offset: 3px;
}

/* ---------- Franja de aviso ---------- */
.aviso {
  --foco: var(--tinta);
  margin: 0;
  background: var(--azafran);
  color: var(--tinta);
  padding: .65rem var(--margen);
  font-size: 1rem;
  line-height: 1.4;
  font-weight: 600;
  text-align: center;
}

/* ---------- Cabecera ---------- */
.cabecera {
  background: var(--tinta);
  border-bottom: 1px solid rgba(238, 240, 245, .14);
  position: relative;
  z-index: 20;
}

.cabecera__in {
  max-width: var(--ancho);
  margin: 0 auto;
  padding: .35rem var(--margen);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0 1.75rem;
}

.marca {
  display: inline-flex;
  align-items: center;
  min-height: 48px;
  font-size: 1.5rem;
  font-weight: 800;
  font-stretch: 72%;
  line-height: 1.05;
  color: var(--papel);
  text-decoration: none;
}

.menu {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  gap: 0 1.25rem;
}

.menu a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 1rem;
  font-weight: 500;
  color: var(--papel);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-decoration-thickness: 2px;
  text-underline-offset: 6px;
  transition: text-decoration-color .15s;
}

.menu a:hover { text-decoration-color: var(--azafran); }

.cabecera__cta { display: none; }

/* ---------- Botones ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: .75rem 1.5rem;
  border: 2px solid transparent;
  border-radius: 999px;
  font: inherit;
  font-size: 1.0625rem;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  transition: background-color .15s, color .15s, border-color .15s;
}

.btn--azafran { background: var(--azafran); color: var(--tinta); }
.btn--azafran:hover { background: var(--papel); }

.btn--tinta { background: var(--tinta); color: var(--papel); }
.btn--tinta:hover { background: var(--tinta-2); }

.btn--borde { background: transparent; border-color: currentColor; color: inherit; }
.btn--borde:hover { background: var(--tinta); border-color: var(--tinta); color: var(--papel); }

/* ---------- Portada ---------- */
.hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: 88vh;
  min-height: 88svh;
  display: flex;
  align-items: flex-end;
}

.hero__foto {
  position: absolute;
  inset: 0;
  z-index: -2;
  margin: 0;
}

.hero__foto img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__velo {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(to top,
    rgba(27, 31, 58, .95) 0%,
    rgba(27, 31, 58, .8) 45%,
    rgba(27, 31, 58, .4) 78%,
    rgba(27, 31, 58, .25) 100%);
}

.hero--tipo {
  --foco: var(--tinta);
  background: var(--azafran);
  color: var(--tinta);
}

/* Espejo redondo de peluquería, solo en la versión sin fotos */
.hero--tipo::before {
  content: "";
  position: absolute;
  z-index: -1;
  width: min(135vw, 64rem);
  aspect-ratio: 1;
  top: -18%;
  right: -48%;
  border: 2px solid var(--tinta);
  border-radius: 50%;
}

.hero__in {
  width: 100%;
  max-width: var(--ancho);
  margin: 0 auto;
  padding: 7rem var(--margen) 3rem;
}

.hero__titulo {
  margin: 0 0 1.5rem;
  max-width: 14ch;
  font-size: clamp(3.25rem, 14vw, 10.5rem);
  font-weight: 800;
  font-stretch: 66%;
  line-height: .88;
  letter-spacing: -.01em;
  overflow-wrap: break-word;
  hyphens: auto;
  text-wrap: balance;
}

.hero__bajada {
  margin: 0 0 2rem;
  max-width: 36ch;
  font-size: clamp(1.125rem, 2vw, 1.375rem);
  line-height: 1.45;
}

.hero--tipo .hero__cta { background: var(--tinta); color: var(--papel); }
.hero--tipo .hero__cta:hover { background: var(--tinta-2); }

@media (prefers-reduced-motion: no-preference) {
  .hero__titulo { animation: subir .9s cubic-bezier(.2, .7, .2, 1) both; }
  .hero__bajada,
  .hero__acciones { animation: subir .9s .18s cubic-bezier(.2, .7, .2, 1) both; }
}

@keyframes subir {
  from { opacity: 0; transform: translateY(1.25rem); }
}

/* ---------- Títulos de sección ---------- */
.titulo-seccion {
  margin: 0;
  font-size: clamp(2.75rem, 10vw, 6.5rem);
  font-weight: 800;
  font-stretch: 68%;
  line-height: .9;
  letter-spacing: -.005em;
}

/* ---------- Servicios ---------- */
.servicios {
  background: var(--tinta);
  color: var(--papel);
  padding: 5rem var(--margen);
}

.servicios__in {
  max-width: var(--ancho);
  margin: 0 auto;
  display: grid;
  gap: 2.5rem;
}

.servicios__lado {
  display: grid;
  gap: 2rem;
  align-content: start;
}

/* Marco en arco, como los espejos del local */
.servicios__foto {
  margin: 0;
  max-width: 26rem;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  border-radius: 999px 999px 0 0;
}

.servicios__foto img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.lista {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: servicio;
}

.lista__item {
  counter-increment: servicio;
  display: grid;
  grid-template-columns: 3rem minmax(0, 1fr);
  gap: 0 1rem;
  padding: 2.25rem 0;
  border-top: 1px solid rgba(238, 240, 245, .2);
}

.lista__item:last-child { border-bottom: 1px solid rgba(238, 240, 245, .2); }

.lista__item::before {
  content: counter(servicio, decimal-leading-zero);
  padding-top: .35rem;
  font-size: 1.125rem;
  font-weight: 700;
  font-stretch: 75%;
  color: var(--azafran);
}

.lista__titulo {
  margin: 0 0 .6rem;
  font-size: clamp(1.625rem, 4vw, 2.5rem);
  font-weight: 700;
  font-stretch: 80%;
  line-height: 1.05;
  overflow-wrap: break-word;
}

.lista__desc {
  margin: 0;
  max-width: 52ch;
  color: var(--niebla);
}

/* ---------- Trabajos ---------- */
.galeria {
  --foco: var(--tinta);
  background: var(--papel);
  color: var(--tinta);
  padding: 5rem 0 4px;
}

.galeria__cab {
  max-width: var(--ancho);
  margin: 0 auto 2.5rem;
  padding: 0 var(--margen);
}

.galeria__grilla {
  list-style: none;
  margin: 0;
  padding: 0 4px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
}

.galeria__grilla figure {
  margin: 0;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  background: var(--tinta);
}

.galeria__grilla img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ---------- Nosotros ---------- */
.nosotros {
  --foco: var(--tinta);
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--papel);
  color: var(--tinta);
  padding: 5rem var(--margen);
}

.nosotros--foto {
  --foco: var(--azafran);
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  align-items: flex-end;
  background: var(--tinta);
  color: var(--papel);
}

.nosotros__foto {
  position: absolute;
  inset: 0;
  z-index: -2;
  margin: 0;
}

.nosotros__foto img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.nosotros__velo {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(to top,
    rgba(27, 31, 58, .96) 0%,
    rgba(27, 31, 58, .82) 50%,
    rgba(27, 31, 58, .35) 100%);
}

.nosotros__in {
  width: 100%;
  max-width: var(--ancho);
  margin: 0 auto;
}

.nosotros__texto {
  margin: 1.75rem 0 2rem;
  max-width: 38ch;
  font-size: clamp(1.25rem, 2.6vw, 1.875rem);
  font-weight: 500;
  font-stretch: 90%;
  line-height: 1.35;
}

.destacados {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  max-width: 48rem;
}

.destacados li {
  padding: .55rem 1.1rem;
  border: 1.5px solid currentColor;
  border-radius: 999px;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
}

/* ---------- Contacto ---------- */
.contacto {
  --foco: var(--tinta);
  background: var(--azafran);
  color: var(--tinta);
  padding: 5rem var(--margen);
}

.contacto__in {
  max-width: var(--ancho);
  margin: 0 auto;
  display: grid;
  gap: 3rem;
}

.contacto__principal .btn { margin-top: 2rem; }

.contacto__datos {
  display: grid;
  gap: 2.25rem;
  align-content: start;
}

.contacto__sub {
  margin: 0 0 .5rem;
  font-size: 1.125rem;
  font-weight: 700;
}

.contacto__dir {
  margin: 0 0 1.25rem;
  font-size: clamp(1.75rem, 5vw, 3rem);
  font-weight: 700;
  font-stretch: 78%;
  line-height: 1.05;
  overflow-wrap: break-word;
}

.contacto__tel {
  display: inline-flex;
  align-items: center;
  min-height: 48px;
  font-size: clamp(1.75rem, 5vw, 3rem);
  font-weight: 700;
  font-stretch: 78%;
  line-height: 1.05;
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 6px;
}

.contacto__botones {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}

/* ---------- Pie ---------- */
.pie {
  background: var(--tinta);
  color: var(--papel);
  padding: 3rem var(--margen);
}

.pie__in {
  max-width: var(--ancho);
  margin: 0 auto;
  display: grid;
  gap: 1.5rem;
}

.pie__nombre {
  margin: 0;
  font-size: 1.75rem;
  font-weight: 800;
  font-stretch: 72%;
  line-height: 1.05;
}

.pie__datos {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: .25rem;
  color: var(--niebla);
}

.pie__datos a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--papel);
}

/* ---------- Barra fija en celular ---------- */
.barra {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 30;
  display: flex;
  gap: .5rem;
  padding: .6rem .75rem calc(.6rem + env(safe-area-inset-bottom));
  background: rgba(27, 31, 58, .97);
  border-top: 1px solid rgba(238, 240, 245, .16);
}

.barra__principal { flex: 2 1 0; }

.barra__llamar {
  flex: 1 1 0;
  color: var(--papel);
}

.barra__llamar:hover { background: var(--tinta-2); border-color: var(--papel); }

/* ---------- Pantallas medianas ---------- */
@media (min-width: 760px) {
  :root { --margen: 2.5rem; }

  .galeria__grilla { grid-template-columns: repeat(3, minmax(0, 1fr)); }

  .contacto__in { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: start; }

  .pie__in { grid-template-columns: minmax(0, 1fr) auto; align-items: end; }
}

/* ---------- Computadora ---------- */
@media (min-width: 960px) {
  body { padding-bottom: 0; }

  .barra { display: none; }

  .cabecera {
    position: sticky;
    top: 0;
  }

  .cabecera__in { flex-wrap: nowrap; }

  .menu {
    width: auto;
    margin-left: auto;
    gap: 0 1.75rem;
  }

  .cabecera__cta { display: inline-flex; }

  section[id] { scroll-margin-top: 4.5rem; }

  .hero {
    min-height: calc(100vh - 7rem);
    min-height: calc(100svh - 7rem);
  }

  .hero__in { padding-bottom: 4.5rem; }

  .servicios { padding-block: 8rem; }

  .servicios__in {
    grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
    gap: 5rem;
    align-items: start;
  }

  .servicios__lado {
    position: sticky;
    top: 7rem;
  }

  .galeria { padding-top: 8rem; }

  .nosotros { padding-block: 8rem; }

  .contacto { padding-block: 8rem; }
}

@media (min-width: 1280px) {
  .galeria__grilla { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

*,*::before,*::after{box-sizing:border-box}
:root{
  --negro:#14120F;
  --crema:#EEE7DA;
  --gris:#A39B8E;
  --bronce:#C9965B;
  --bronce-claro:#DDB07A;
  --linea:rgba(238,231,218,.08);
  --regla:rgba(238,231,218,.26);
  --m:1.25rem;
  --p:.625rem;
  --cols:4;
  --ancho:min(100% - 2 * var(--m), 80rem);
}
@media (min-width:600px){:root{--cols:6;--m:2rem}}
@media (min-width:900px){:root{--cols:12;--m:2.5rem;--p:.75rem}}

html{background:var(--negro);color:var(--crema);-webkit-text-size-adjust:100%}
body{margin:0;font-family:"Archivo",system-ui,sans-serif;font-size:1.125rem;line-height:1.55;position:relative;min-height:100vh;overflow-x:hidden}
body::before{content:"";position:absolute;top:0;bottom:0;left:0;right:0;margin-inline:auto;width:var(--ancho);z-index:-1;pointer-events:none;background:linear-gradient(to right,var(--linea) 1px,transparent 1px) 0 0/calc(100% / var(--cols)) 100% repeat-x;border-right:1px solid var(--linea)}
h1,h2,h3,p,figure{margin:0}
img{display:block;width:100%;height:auto}
::selection{background:var(--bronce);color:var(--negro)}
a{color:inherit}
:focus-visible{outline:3px solid var(--crema);outline-offset:3px}

/* Grilla */
.wrap{width:var(--ancho);margin-inline:auto}
.grid{display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr))}
:where(.grid,.sub)>*{grid-column:1/-1;min-width:0}
:where(.grid,.sub)>:where(:not(.sub)){padding-inline:var(--p)}
.sub{display:grid;grid-template-columns:subgrid;margin:0;padding:0;list-style:none}

/* Saltar */
.saltar{position:absolute;left:var(--m);top:-4rem;z-index:20;background:var(--crema);color:var(--negro);padding:.75rem 1rem;font-weight:700;text-decoration:none}
.saltar:focus{top:.5rem}

/* Aviso */
.aviso{background:var(--crema);color:var(--negro)}
.aviso p{padding:.75rem var(--p);font-size:1rem;line-height:1.4;font-weight:500}

/* Encabezado */
.cab{border-bottom:1px solid var(--regla)}
.cab-in{padding-block:1rem .5rem;align-items:center}
.marca{font-weight:800;font-stretch:80%;font-size:1.625rem;line-height:1.1;letter-spacing:-.01em;color:var(--crema);text-decoration:none;justify-self:start}
.menu ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;column-gap:1.25rem}
.menu a{display:inline-flex;align-items:center;min-height:44px;font-size:1rem;font-weight:500;color:var(--crema);text-decoration:none;border-bottom:2px solid transparent}
.menu a:hover{color:var(--bronce-claro)}
.menu a[aria-current="page"]{border-bottom-color:var(--bronce)}
.cab-cta{display:none}

/* Botones y links */
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:.75rem 1.25rem;background:var(--bronce);color:var(--negro);border:2px solid var(--bronce);border-radius:0;font-size:1rem;font-weight:700;line-height:1.2;text-decoration:none;text-align:center}
.btn:hover{background:var(--bronce-claro);border-color:var(--bronce-claro)}
.btn-linea{background:transparent;color:var(--crema);border-color:var(--regla)}
.btn-linea:hover{background:transparent;color:var(--crema);border-color:var(--crema)}
.link{display:inline-flex;align-items:center;min-height:44px;color:var(--bronce);font-weight:600;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:.25em}
.link:hover{color:var(--bronce-claro)}
.acciones{display:flex;flex-wrap:wrap;gap:.75rem}

/* Portada */
.hero{padding-top:2.5rem}
.titular{font-size:clamp(2.75rem,7.5vw + 1rem,8.5rem);font-weight:800;font-stretch:78%;line-height:.92;letter-spacing:-.02em;color:var(--bronce);overflow-wrap:break-word;hyphens:auto;margin-bottom:2rem;animation:subir .8s cubic-bezier(.2,.7,.2,1) both}
@keyframes subir{from{opacity:0;transform:translateY(.2em)}}
.hero-txt{display:flex;flex-direction:column;gap:1.5rem;margin-bottom:2rem}
.bajada{font-size:1.25rem;line-height:1.45;max-width:34ch}
.hero-foto{margin-bottom:2rem}
.hero-foto img{aspect-ratio:4/3;object-fit:cover}
.hero-tipo{position:relative;background:var(--crema);color:var(--negro);padding:3.5rem 1.25rem 1.25rem;margin-bottom:2rem;min-height:18rem;display:flex;flex-direction:column;justify-content:space-between;gap:2rem}
.hero-tipo::before{content:"";position:absolute;top:1.25rem;left:1.25rem;width:1.25rem;height:1.25rem;background:var(--bronce)}
.tipo-nombre{font-size:clamp(2.5rem,6vw + 1rem,6.5rem);font-weight:800;font-stretch:68%;line-height:.88;letter-spacing:-.02em;overflow-wrap:anywhere}
.tipo-dir{font-size:1rem;font-weight:600;border-top:2px solid var(--negro);padding-top:.75rem}
.destacados{border-top:1px solid var(--regla)}
.destacados li{padding-block:1rem 1.25rem;font-size:1.0625rem;font-weight:600;line-height:1.35;border-bottom:1px solid var(--regla)}
.destacados li::before{content:"";display:block;width:2rem;height:3px;background:var(--bronce);margin-bottom:.75rem}

/* Secciones */
.seccion{border-top:1px solid var(--regla);padding-block:3rem 3.5rem}
.hero + .seccion{border-top:0}
.sec-tit{font-size:1.5rem;font-weight:700;line-height:1.2;margin-bottom:1.5rem}

.serv-lista>li{border-top:1px solid var(--regla);padding-block:1.25rem;row-gap:.375rem}
.serv-lista>li:last-child{border-bottom:1px solid var(--regla)}
.serv-lista h3{font-size:1.5rem;font-weight:700;font-stretch:88%;line-height:1.15}
.serv-lista p{color:var(--gris)}

.sobre{font-size:1.25rem;line-height:1.55;max-width:40ch}

.gal>li{grid-column:span 2;margin-bottom:1.25rem}
.gal img{aspect-ratio:1/1;object-fit:cover}

.llegar-dir{font-size:clamp(1.75rem,3vw + 1rem,3rem);font-weight:700;font-stretch:85%;line-height:1.1;margin-bottom:1.25rem;max-width:20ch}

/* Páginas internas */
.pag-cab{padding-block:2.5rem 2rem}
.pag-tit{font-size:clamp(3rem,6vw + 1rem,7rem);font-weight:800;font-stretch:78%;line-height:.92;letter-spacing:-.02em;color:var(--bronce);overflow-wrap:break-word;hyphens:auto;animation:subir .8s cubic-bezier(.2,.7,.2,1) both}

.serv-grande>li{border-top:1px solid var(--regla);padding-block:2rem;row-gap:1rem}
.serv-grande>li:last-child{border-bottom:1px solid var(--regla)}
.sg-tit{font-size:clamp(2rem,3.5vw + 1rem,4.25rem);font-weight:800;font-stretch:80%;line-height:.95;letter-spacing:-.015em;overflow-wrap:break-word}
.sg-cuerpo{display:flex;flex-direction:column;align-items:flex-start;gap:1rem}
.sg-cuerpo p{color:var(--gris);max-width:44ch}

.turnos>li{margin:0 var(--p) 1rem;padding:1.25rem 0 2rem;border-top:2px solid var(--bronce);display:flex;flex-direction:column;gap:.75rem}
.turnos h2{font-size:1.5rem;font-weight:700;font-stretch:88%;line-height:1.15}
.turnos p{color:var(--gris);flex:1}
.turnos .acciones{margin-top:.5rem}
.otra-via{border-top:1px solid var(--regla);padding-block:2rem 3rem}
.otra-via .sec-tit{margin-bottom:1rem}

.cto-bloque{margin-bottom:2.5rem}
.cto-tel{display:inline-block;font-size:clamp(2rem,4vw + 1rem,4.5rem);font-weight:800;font-stretch:80%;line-height:1;letter-spacing:-.01em;color:var(--crema);text-decoration:underline;text-decoration-color:var(--bronce);text-decoration-thickness:3px;text-underline-offset:.15em;padding-block:.25rem;margin-bottom:1.5rem;overflow-wrap:anywhere}
.cto-tel:hover{text-decoration-color:var(--crema)}

/* Pie */
.pie{border-top:1px solid var(--regla);padding-block:3rem 7rem}
.pie-marca{font-size:2rem;font-weight:800;font-stretch:78%;line-height:1;letter-spacing:-.01em;margin-bottom:2rem}
.pie-col{margin-bottom:2rem}
.pie-tit{font-size:1rem;font-weight:700;color:var(--gris);margin-bottom:.25rem}
.pie-col p{font-size:1rem}
.pie-col a,.pie-nav a{display:flex;align-items:center;min-height:44px;font-size:1rem;text-decoration:none;color:var(--crema)}
.pie-col a:hover,.pie-nav a:hover{color:var(--bronce-claro)}
.pie-nav ul{list-style:none;margin:0;padding:0}

/* Barra celular */
.barra{position:fixed;left:0;right:0;bottom:0;z-index:10;display:flex;gap:.5rem;padding:.625rem var(--m) calc(.625rem + env(safe-area-inset-bottom));background:var(--negro);border-top:1px solid var(--regla)}
.barra .btn{flex:1}

@media (min-width:600px){
  .gal>li{grid-column:span 2}
  .turnos>li{grid-column:span 3}
  .destacados li{grid-column:span 3}
}
@media (min-width:900px){
  .cab-in{padding-block:1.25rem}
  .marca{grid-column:1/span 3}
  .menu{grid-column:4/span 6}
  .cab-cta{display:block;grid-column:10/-1}
  .hero{padding-top:4rem}
  .titular{grid-column:1/span 11;margin-bottom:3rem}
  .hero-txt{grid-column:1/span 4;margin-bottom:3rem}
  .hero-foto{grid-column:5/-1;margin-bottom:3rem}
  .hero-tipo{grid-column:6/-1;margin-bottom:3rem;min-height:24rem}
  .destacados li{grid-column:span 3;border-bottom:0}
  .seccion{padding-block:4.5rem 5rem}
  .sec-tit{grid-column:1/span 3}
  .serv-lista{grid-column:4/-1}
  .serv-lista h3{grid-column:1/span 4}
  .serv-lista p{grid-column:5/span 3}
  .serv-acc{grid-column:8/-1}
  .sobre{grid-column:4/span 7;font-size:1.375rem}
  .gal{grid-column:4/-1}
  .gal>li{grid-column:span 3}
  .llegar{grid-column:4/-1}
  .pag-cab{padding-block:4rem 3rem}
  .pag-tit{grid-column:1/span 11}
  .sg-tit{grid-column:1/span 7}
  .sg-cuerpo{grid-column:8/-1}
  .turnos>li{grid-column:span 4}
  .otra-via .acciones{grid-column:4/-1}
  .cto-bloque{grid-column:1/span 6}
  .cto-llegar{grid-column:7/-1}
  .pie{padding-block:4rem}
  .pie-marca{grid-column:1/span 4}
  .pie-col{grid-column:span 3}
  .pie-nav{grid-column:11/-1}
  .barra{display:none}
}
@media (prefers-reduced-motion:reduce){
  .titular,.pag-tit{animation:none}
}

:root{
  --papel:#FFFFFF;
  --tinta:#000000;
  --gris:#575757;
  --linea:#E2E2E2;
  --acento:#1F3BD0;
  --gris-claro:#BDBDBD;
  --col:4;
  --gap:1rem;
  --margen:1.25rem;
  --sans:"Archivo","Helvetica Neue",Arial,sans-serif;
  --mono:"IBM Plex Mono",ui-monospace,Menlo,Consolas,monospace;
}
@media (min-width:48rem){
  :root{--col:12;--gap:1.5rem;--margen:2.5rem;}
}
*,*::before,*::after{box-sizing:border-box;}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;}
body{
  margin:0;
  font-family:var(--sans);
  font-size:1.0625rem;
  line-height:1.5;
  color:var(--tinta);
  background:var(--papel);
  overflow-x:clip;
  padding-bottom:5.5rem;
}
@media (min-width:48rem){
  body{font-size:1.125rem;padding-bottom:0;}
}
img{display:block;max-width:100%;height:auto;}
a{color:inherit;}
:focus-visible{outline:3px solid var(--acento);outline-offset:3px;}

/* Grilla */
.marco{width:100%;max-width:90rem;margin-inline:auto;padding-inline:var(--margen);}
.grilla{display:grid;grid-template-columns:repeat(var(--col),minmax(0,1fr));column-gap:var(--gap);}
.con-lineas{position:relative;}
.con-lineas::before{
  content:"";
  position:absolute;
  top:0;bottom:0;left:var(--margen);right:var(--margen);
  pointer-events:none;
  border-right:1px solid var(--linea);
  background-image:repeating-linear-gradient(to right,var(--linea) 0 1px,transparent 1px calc((100% + var(--gap)) / var(--col)));
  z-index:0;
}
.con-lineas > *{position:relative;z-index:1;}

/* Aviso */
.aviso{background:var(--tinta);color:var(--papel);}
.aviso p{margin:0;padding-block:.75rem;font-size:1rem;line-height:1.4;}

/* Cabecera */
.cabecera{border-bottom:1px solid var(--tinta);background:var(--papel);}
.cabecera-fila{display:flex;flex-wrap:wrap;align-items:center;gap:0 2rem;padding-block:.75rem;}
.marca{
  display:inline-flex;align-items:center;min-height:44px;margin-right:auto;
  font-weight:700;font-size:1.25rem;letter-spacing:-.015em;text-decoration:none;
}
.menu{flex-basis:100%;order:3;}
.menu ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:0 1.25rem;}
.menu a{
  display:inline-flex;align-items:center;min-height:44px;
  font-size:1rem;text-decoration:none;
}
.menu a:hover{text-decoration:underline;text-decoration-color:var(--acento);text-decoration-thickness:2px;text-underline-offset:.35em;}
.boton-cabecera{display:none;}
@media (min-width:48rem){
  .menu{flex-basis:auto;order:0;}
  .menu ul{gap:0 2rem;}
  .boton-cabecera{display:inline-flex;}
}

/* Botones */
.boton{
  display:inline-flex;align-items:center;justify-content:center;
  min-height:3rem;padding:.75rem 1.5rem;
  background:var(--acento);color:var(--papel);
  border:1px solid var(--acento);
  font-family:var(--sans);font-size:1rem;font-weight:600;line-height:1.2;
  text-decoration:none;text-align:center;
}
.boton:hover{background:var(--tinta);border-color:var(--tinta);}
.boton-linea{background:var(--papel);color:var(--tinta);border-color:var(--tinta);}
.boton-linea:hover{background:var(--tinta);color:var(--papel);}

/* Etiquetas funcionales */
.etiqueta{font-family:var(--mono);font-size:1rem;font-weight:400;line-height:1.45;}

/* Portada */
.portada{padding-top:2.5rem;}
.portada .con-lineas::before{transform-origin:top;animation:trazo 1s cubic-bezier(.2,.7,.2,1) both;}
@keyframes trazo{from{transform:scaleY(0);}to{transform:scaleY(1);}}
.titular{
  grid-column:1/-1;
  margin:0 0 2.5rem;
  font-size:clamp(2.5rem,1.2rem + 6vw,7.5rem);
  font-weight:700;
  line-height:.95;
  letter-spacing:-.035em;
  overflow-wrap:break-word;
  hyphens:auto;
  text-wrap:balance;
}
.portada-dato{grid-column:1/-1;margin:0 0 1.5rem;}
.portada-texto{grid-column:1/-1;}
.bajada{margin:0;font-size:1.25rem;line-height:1.4;max-width:34ch;}
.portada-texto .boton{margin-top:1.75rem;}
.portada-foto{grid-column:1/-1;margin:3rem 0 0;}
.portada-foto img{width:100%;aspect-ratio:4/3;object-fit:cover;}
.portada-tipo{
  --linea:rgba(255,255,255,.28);
  background:var(--acento);color:var(--papel);
  padding-bottom:4rem;
}
.portada-tipo .boton{background:var(--papel);color:var(--acento);border-color:var(--papel);}
.portada-tipo .boton:hover{background:var(--tinta);color:var(--papel);border-color:var(--tinta);}
.portada-tipo :focus-visible{outline-color:var(--papel);}
@media (min-width:48rem){
  .portada{padding-top:5rem;}
  .titular{grid-column:1/12;margin-bottom:4rem;}
  .portada-dato{grid-column:1/5;margin:.35rem 0 0;}
  .portada-texto{grid-column:5/11;}
  .bajada{font-size:1.4375rem;}
  .portada-foto{margin-top:5rem;}
  .portada-foto img{aspect-ratio:16/9;}
  .portada-tipo{padding-bottom:7rem;}
}

/* Secciones */
.seccion{border-top:1px solid var(--tinta);}
.seccion > .marco{padding-block:4rem;}
.seccion-titulo{
  grid-column:1/-1;align-self:start;
  margin:0 0 2rem;
  font-size:clamp(1.75rem,1.35rem + 1.6vw,2.75rem);
  font-weight:700;line-height:1.05;letter-spacing:-.025em;
}
@media (min-width:48rem){
  .seccion > .marco{padding-block:6rem;}
  .seccion-titulo{grid-column:1/5;margin:0;}
}

/* Servicios */
.servicios-lista{grid-column:1/-1;list-style:none;margin:0;padding:0;border-bottom:1px solid var(--tinta);}
.servicio{display:grid;gap:.5rem;padding-block:1.5rem;border-top:1px solid var(--tinta);background:var(--papel);}
.servicio h3{margin:0;font-size:1.375rem;font-weight:600;line-height:1.2;letter-spacing:-.01em;}
.servicio p{margin:0;color:var(--gris);max-width:42ch;}
@media (min-width:48rem){
  .servicios-lista{grid-column:5/-1;}
  .servicio{grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:var(--gap);padding-block:2rem;}
  .servicio h3{font-size:1.5rem;}
}

/* Proyectos */
.galeria,.galeria-vacia{
  grid-column:1/-1;list-style:none;margin:0;padding:0;
  display:grid;grid-template-columns:minmax(0,1fr);gap:var(--gap);
}
.galeria img{width:100%;aspect-ratio:4/3;object-fit:cover;background:var(--linea);}
.marco-vacio{
  aspect-ratio:4/3;
  display:flex;align-items:center;justify-content:center;
  border:1px solid var(--tinta);
  background:
    linear-gradient(to top right,transparent calc(50% - .5px),var(--gris-claro) 50%,transparent calc(50% + .5px)),
    linear-gradient(to bottom right,transparent calc(50% - .5px),var(--gris-claro) 50%,transparent calc(50% + .5px)),
    var(--papel);
}
.marco-vacio span{background:var(--papel);padding:.5rem .75rem;}
@media (min-width:48rem){
  .galeria,.galeria-vacia{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:3rem;}
}

/* Estudio */
.estudio-texto{grid-column:1/-1;}
.sobre{margin:0;font-size:clamp(1.25rem,1.05rem + .7vw,1.625rem);line-height:1.42;letter-spacing:-.005em;max-width:38em;}
.destacados{list-style:none;margin:2.5rem 0 0;padding:0;border-bottom:1px solid var(--tinta);}
.destacados li{padding-block:1rem;border-top:1px solid var(--tinta);background:var(--papel);}
@media (min-width:48rem){
  .estudio-texto{grid-column:5/12;}
}

/* Contacto */
.contacto{
  --linea:rgba(255,255,255,.16);
  background:var(--tinta);color:var(--papel);border-top:0;
}
.contacto :focus-visible{outline-color:var(--papel);}
.contacto-datos{grid-column:1/-1;margin:0;display:grid;gap:2rem;}
.contacto-datos dt{color:var(--gris-claro);margin-bottom:.35rem;}
.contacto-datos dd{margin:0;font-size:1.375rem;line-height:1.3;}
.contacto-datos a{display:inline-block;padding-block:.5rem;text-underline-offset:.2em;text-decoration-thickness:1px;}
.contacto-datos a:hover{text-decoration-thickness:3px;}
.contacto-boton{grid-column:1/-1;margin-top:2.5rem;}
@media (min-width:48rem){
  .contacto-datos{grid-column:5/-1;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:var(--gap);row-gap:3rem;}
  .contacto-datos dd{font-size:1.625rem;}
  .contacto-boton{grid-column:5/-1;margin-top:3.5rem;}
}

/* Pie */
.pie{border-top:1px solid var(--tinta);}
.pie .marco{padding-block:2rem;row-gap:.25rem;}
.pie p{grid-column:1/-1;margin:0;}
.pie a{display:inline-flex;align-items:center;min-height:44px;text-underline-offset:.2em;}
.pie-nombre{font-weight:700;display:flex;align-items:center;min-height:44px;}
@media (min-width:48rem){
  .pie-nombre{grid-column:1/5 !important;}
  .pie-direccion{grid-column:5/9 !important;}
  .pie-telefono{grid-column:9/11 !important;}
  .pie-arriba{grid-column:11/-1 !important;justify-self:end;}
}

/* Barra fija en celular */
.barra-movil{
  position:fixed;left:0;right:0;bottom:0;z-index:50;
  display:flex;gap:.5rem;
  padding:.75rem var(--margen) calc(.75rem + env(safe-area-inset-bottom));
  background:var(--papel);border-top:1px solid var(--tinta);
}
.barra-movil .boton{flex:1 1 0;min-height:3rem;}
@media (min-width:48rem){
  .barra-movil{display:none;}
}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto;}
  .portada .con-lineas::before{animation:none;}
}
